from abc import ABC, abstractmethod

from bank_connector.app.schemas.connector import (
    AuthorizeRequest,
    CaptureRequest,
    ProcessorResponse,
    RefundRequest,
    VoidRequest,
)


class BaseProcessor(ABC):
    """
    Abstract interface all processors must implement.

    Adding a new processor (e.g. Adyen):
    1. Create adyen_processor.py
    2. Inherit BaseProcessor
    3. Implement all methods
    4. Register in router.py

    Payment Service never changes - only the processor does.
    """

    @property
    @abstractmethod
    def name(self) -> str:
        """Processor name: stripe | adyen | mock"""
        ...

    @abstractmethod
    async def authorize(self, request: AuthorizeRequest) -> ProcessorResponse:
        """
        Hold funds on card without charging.
        Returns authorization code needed for capture.
        """
        ...

    @abstractmethod
    async def capture(self, request: CaptureRequest) -> ProcessorResponse:
        """
        Charge the held funds.
        Must be called within 7 days of authorize.
        """
        ...

    @abstractmethod
    async def refund(self, request: RefundRequest) -> ProcessorResponse:
        """
        Return money to customer after capture.
        """
        ...

    @abstractmethod
    async def void(self, request: VoidRequest) -> ProcessorResponse:
        """
        Cancel authorization before capture.
        No money movement.
        """
        ...

    @abstractmethod
    async def health_check(self) -> bool:
        """Returns True if processor is reachable"""
        ...
